#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  chmod 600 "$ENV_FILE"   # before the secret lands, even if the file was looser
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# unset_env KEY removes KEY's line from ENV_FILE, if any.
unset_env() {
  local tmp; tmp=$(mktemp)
  grep -vE "^${1}=" "$ENV_FILE" > "$tmp" || true
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf '  %s✓ removed%s %s from %s\n' "$GREEN" "$RESET" "$1" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Cloudflare setup for the Leaderboard site (PLAN.md, Sprint 9, S9.2).
#
#   scripts/setup_cloudflare.sh              run the wizard
#   scripts/setup_cloudflare.sh --self-test  test the offline helpers (no network)
#
# Every stage checks what already exists and skips what is done, so re-running
# after a failure or Ctrl-C picks up where it stopped. Secrets are read with
# hidden input, handed to curl and gh on stdin, and never printed.
#
# Writes (both gitignored):
#   site/.cloudflare-ids.env  account id, Pages project and KV namespace ids (not secret)
#   .env.leaderboard          the home machine's KV push token and ntfy topic (mode 600)

PAGES_PROJECT="ffp-leaderboard"
PAGES_BRANCH="main"
KV_TITLE="ffp-leaderboard"            # wrangler appends "_preview" for the preview namespace
KV_PREVIEW_TITLE="${KV_TITLE}_preview"
WRANGLER_PKG="wrangler@4"             # major pinned; commands checked against wrangler 4.165
CF_API="https://api.cloudflare.com/client/v4"
TOKENS_URL="https://dash.cloudflare.com/profile/api-tokens"
IDS_FILE="site/.cloudflare-ids.env"
SECRETS_FILE=".env.leaderboard"
SCRIPT_PATH="scripts/setup_cloudflare.sh"
CF_ACCOUNT_ID=""
WR_DIR=""

die() {
  printf '\n  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2
  [[ -n "${2:-}" ]] && printf '  %s\n' "$2" >&2
  printf '\n  %sFix the problem and re-run %s; finished stages are detected and skipped.%s\n\n' \
    "$DIM" "$SCRIPT_PATH" "$RESET" >&2
  exit 1
}
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# shellcheck disable=SC2329  # called from the ERR trap
_on_err() {
  printf '\n  %s✗ Stopped: a command failed in stage %s/%s (line %s).%s\n' \
    "$YELLOW" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" >&2
  printf '  %sRead the message above, fix it, and re-run %s; finished stages are skipped.%s\n\n' \
    "$DIM" "$SCRIPT_PATH" "$RESET" >&2
}

# ── Offline helpers (covered by --self-test) ──────────────────────────────
# Each reads JSON on stdin. wrangler can print notices before its JSON, so
# parsing starts at the first line that opens an object or array.

# _node_json 'JS body using data and arg' [arg]: return false → exit 1,
# unparsable JSON → exit 2, a string → printed.
_node_json() {
  node -e '
    const raw = require("fs").readFileSync(0, "utf8");
    const m = raw.match(/^[ \t]*[\[{]/m);
    let data;
    try { data = JSON.parse(m ? raw.slice(m.index) : raw); } catch (e) { process.exit(2); }
    const out = (function (data, arg) { '"$1"' })(data, process.argv[1]);
    if (out === false) process.exit(1);
    if (out !== undefined && out !== true) process.stdout.write(String(out));
  ' "${2:-}"
}

# wrangler whoami --json → one "id<TAB>name" line per account
whoami_accounts() { _node_json 'return (data.accounts || []).map(a => a.id + "\t" + a.name).join("\n");'; }
# wrangler kv namespace list → id of the namespace titled $1 (empty if none)
kv_id_for_title() { _node_json 'const n = data.find(x => x.title === arg); return n ? n.id : "";' "$1"; }
# wrangler pages project list --json → "domain<TAB>git provider" for project $1; fails if absent
pages_project_info() {
  _node_json 'const p = data.find(x => x["Project Name"] === arg);
    if (!p) return false; return p["Project Domains"] + "\t" + p["Git Provider"];' "$1"
}
# any Cloudflare API response → succeeds iff "success": true
cf_success() { _node_json 'return data.success === true;'; }
# /tokens/verify response → the token status ("active", "disabled", "expired"), empty if invalid
cf_token_status() { _node_json 'return data.success === true && data.result ? data.result.status : "";'; }

valid_ntfy_topic() { [[ "$1" =~ ^[A-Za-z0-9_-]{16,64}$ ]]; }
make_ntfy_topic()  { printf 'ffp-alerts-%s' "$(od -An -N10 -tx1 /dev/urandom | tr -d ' \n')"; }
valid_push_secret() { [[ "$1" =~ ^[0-9a-f]{64}$ ]]; }
make_push_secret()  { od -An -N32 -tx1 /dev/urandom | tr -d ' \n'; }
valid_account_id() { [[ "$1" =~ ^[0-9a-f]{32}$ ]]; }

# ── Networked helpers ─────────────────────────────────────────────────────

# wr ARGS runs wrangler from an empty directory, so it never finds or edits a
# wrangler config or leaves caches in the repo, and with the OAuth login
# rather than any CLOUDFLARE_API_TOKEN in the environment.
wr() {
  local acct=()
  [[ -n "$CF_ACCOUNT_ID" ]] && acct=("CLOUDFLARE_ACCOUNT_ID=$CF_ACCOUNT_ID")
  (cd "$WR_DIR" && env -u CLOUDFLARE_API_TOKEN "${acct[@]}" npx --yes "$WRANGLER_PKG" "$@")
}

# cf_call TOKEN METHOD PATH [DATA]: a Cloudflare API call. The token reaches
# curl on stdin, never on its command line. Prints the JSON response.
cf_call() {
  local token="$1" method="$2" path="$3" data="${4:-}"
  {
    printf 'header = "Authorization: Bearer %s"\n' "$token"
    [[ -z "$data" ]] || printf 'data-binary = "%s"\n' "$data"
  } | curl -sS -X "$method" -K - "$CF_API$path" 2>/dev/null \
    || printf '{"success":false,"errors":[{"code":0,"message":"network error"}]}'
}

# verify_token TOKEN: an active user token (or an account-owned one on our account)
verify_token() {
  local status
  status=$(cf_call "$1" GET /user/tokens/verify | cf_token_status || true)
  [[ -n "$status" ]] || status=$(cf_call "$1" GET "/accounts/$CF_ACCOUNT_ID/tokens/verify" | cf_token_status || true)
  [[ "$status" == "active" ]] || die "The token did not verify (status: ${status:-invalid})." \
    "Check you copied the whole token from the page Cloudflare shows once after 'Create Token'."
  ok "token verified: active"
}

# can TOKEN PATH: the token may GET this path under our account
can() { cf_call "$1" GET "/accounts/$CF_ACCOUNT_ID$2" | cf_success; }

gh_secret_exists() { gh secret list --json name -q '.[].name' 2>/dev/null | grep -qx "$1"; }

# ── Self-test ─────────────────────────────────────────────────────────────

self_test() {
  local fails=0 got
  check() {   # check NAME EXPECTED ACTUAL
    if [[ "$2" == "$3" ]]; then printf '  ok   %s\n' "$1"
    else printf '  FAIL %s: expected [%s] got [%s]\n' "$1" "$2" "$3"; fails=$((fails + 1)); fi
  }
  yn() { if "$@" >/dev/null 2>&1; then echo yes; else echo no; fi; }

  local whoami='{"loggedIn":true,"authType":"OAuth Token","email":"a@b.c","accounts":[{"name":"One","id":"0123456789abcdef0123456789abcdef"},{"name":"Two","id":"fedcba9876543210fedcba9876543210"}]}'
  check "whoami_accounts" $'0123456789abcdef0123456789abcdef\tOne\nfedcba9876543210fedcba9876543210\tTwo' \
    "$(printf '%s' "$whoami" | whoami_accounts)"
  check "whoami with no accounts" "" "$(printf '%s' '{"loggedIn":true,"accounts":[]}' | whoami_accounts)"

  local kv=$'▲ [WARNING] a newer wrangler is available\n[\n  {"id": "aaa", "title": "ffp-leaderboard"},\n  {"id": "bbb", "title": "ffp-leaderboard_preview"}\n]'
  check "kv id, after a notice line" "aaa" "$(printf '%s' "$kv" | kv_id_for_title ffp-leaderboard)"
  check "kv preview id" "bbb" "$(printf '%s' "$kv" | kv_id_for_title ffp-leaderboard_preview)"
  check "kv title missing" "" "$(printf '%s' "$kv" | kv_id_for_title other)"
  check "kv empty list" "" "$(printf '[]' | kv_id_for_title ffp-leaderboard)"

  local pages='[{"Project Name":"ffp-leaderboard","Project Domains":"ffp-leaderboard.pages.dev","Git Provider":"No","Last Modified":"x"}]'
  check "pages project found" $'ffp-leaderboard.pages.dev\tNo' "$(printf '%s' "$pages" | pages_project_info ffp-leaderboard)"
  check "pages project absent" "no" "$(printf '%s' "$pages" | yn pages_project_info nope)"
  check "unparsable JSON fails" "no" "$(printf 'not json' | yn pages_project_info x)"

  check "cf_success true" "yes" "$(printf '{"success":true,"result":[]}' | yn cf_success)"
  check "cf_success false" "no" "$(printf '{"success":false,"errors":[{"code":10000,"message":"Authentication error"}]}' | yn cf_success)"
  check "token status active" "active" "$(printf '{"success":true,"result":{"id":"x","status":"active"}}' | cf_token_status)"
  check "token status invalid" "" "$(printf '{"success":false,"errors":[{"code":1000,"message":"Invalid API Token"}]}' | cf_token_status)"

  local t; t=$(make_ntfy_topic)
  check "generated ntfy topic is valid" "yes" "$(yn valid_ntfy_topic "$t")"
  check "ntfy topics are random" "yes" "$(yn test "$t" != "$(make_ntfy_topic)")"
  check "short topic rejected" "no" "$(yn valid_ntfy_topic alerts)"
  check "topic with spaces rejected" "no" "$(yn valid_ntfy_topic 'bad topic with spaces')"
  check "account id accepted" "yes" "$(yn valid_account_id 0123456789abcdef0123456789abcdef)"
  check "account id rejected" "no" "$(yn valid_account_id xyz)"

  # write_env: upsert, quoting and mode 600, on a throwaway file
  local tmpd; tmpd=$(mktemp -d)
  got=$(
    ENV_FILE="$tmpd/e.env"
    write_env K1 "plain" >/dev/null; write_env K2 "it's quoted" >/dev/null; write_env K1 "replaced" >/dev/null
    printf '%s|%s|%s|%s' "$(_existing K1)" "$(_existing K2)" "$(grep -c '^K1=' "$ENV_FILE")" "$(stat -c %a "$ENV_FILE")"
  )
  check "write_env upsert, quoting, mode 600" "replaced|it's quoted|1|600" "$got"
  got=$(
    ENV_FILE="$tmpd/loose.env"; : > "$ENV_FILE"; chmod 644 "$ENV_FILE"
    write_env K1 "secret" >/dev/null
    stat -c %a "$ENV_FILE"
  )
  check "write_env tightens a loose existing file before writing" "600" "$got"
  got=$(
    ENV_FILE="$tmpd/u.env"; write_env A 1 >/dev/null; write_env B 2 >/dev/null; unset_env A >/dev/null
    printf '%s|%s' "$(_existing A || true)" "$(_existing B)"
  )
  check "unset_env removes one key" "|2" "$got"
  got=$(make_push_secret)
  check "push secret is 64 hex characters" "yes" "$(yn valid_push_secret "$got")"
  check "push secrets are random" "yes" "$(yn test "$got" != "$(make_push_secret)")"
  check "short push secret rejected" "no" "$(yn valid_push_secret abc123)"

  # cf_call: the token goes to curl on stdin, never in its argv
  mkdir "$tmpd/bin"
  cat > "$tmpd/bin/curl" <<STUB
#!/usr/bin/env bash
printf '%s\n' "\$*" > "$tmpd/argv"; cat > "$tmpd/stdin"; printf '{"success":true}'
STUB
  chmod +x "$tmpd/bin/curl"
  PATH="$tmpd/bin:$PATH" cf_call "SECRET-TOKEN-123" PUT /x "payload" >/dev/null
  check "token absent from curl argv" "no" "$(yn grep -q SECRET-TOKEN-123 "$tmpd/argv")"
  check "token sent on curl stdin" "yes" "$(yn grep -q 'Bearer SECRET-TOKEN-123' "$tmpd/stdin")"
  check "PUT body sent on curl stdin" "yes" "$(yn grep -q 'data-binary = "payload"' "$tmpd/stdin")"
  rm -rf "$tmpd"

  printf '\n  %s failure(s)\n' "$fails"
  (( fails == 0 ))
}

# ── Stages ────────────────────────────────────────────────────────────────

run_wizard() {

if [[ "${1:-}" == "--self-test" ]]; then self_test; return; fi
if [[ -n "${1:-}" ]]; then printf 'usage: %s [--self-test]\n' "$SCRIPT_PATH" >&2; return 2; fi

cd "$(dirname "${BASH_SOURCE[0]}")/.."
set -E
trap '_on_err $LINENO' ERR
WR_DIR=$(mktemp -d)
trap 'rm -rf "$WR_DIR"' EXIT
ENV_FILE="$SECRETS_FILE"

TOTAL_STAGES=8

banner "Cloudflare setup for the ffp Leaderboard"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Checking the tools this wizard and the deploys need."
command -v node >/dev/null || die "Node.js is not installed." "Install Node 22.12 or newer (https://nodejs.org, or nvm), then re-run."
node -e 'const [a, b] = process.versions.node.split(".").map(Number); process.exit(a > 22 || (a === 22 && b >= 12) ? 0 : 1)' \
  || die "Node $(node --version) is too old: wrangler 4 needs 22.12 or newer." "Upgrade Node (for example 'nvm install 22'), then re-run."
ok "node $(node --version)"
command -v npm >/dev/null || die "npm is not installed." "It ships with Node; reinstall Node, then re-run."
ok "npm $(npm --version)"
command -v curl >/dev/null || die "curl is not installed." "Install it (sudo apt install curl), then re-run."
note "Running npx $WRANGLER_PKG --version (the first run downloads wrangler)..."
WR_VERSION=$(wr --version 2>/dev/null | tail -n1) || die "'npx $WRANGLER_PKG --version' failed." "Check your network and npm, then re-run."
ok "wrangler $WR_VERSION"
command -v gh >/dev/null || die "The GitHub CLI (gh) is not installed." "Install it (https://cli.github.com), run 'gh auth login', then re-run."
gh auth status >/dev/null 2>&1 || die "gh is not logged in." "Run 'gh auth login', then re-run."
GH_REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null) \
  || die "gh can't tell which GitHub repository this is." "Run the wizard from inside the fantasy-football-predictor clone."
export GH_REPO
ok "gh logged in; secrets will go to $GH_REPO"
printf '\n'
say "You also need a Cloudflare account (the free plan is enough)."
if ! confirm "Do you already have a Cloudflare account?"; then
  open_url "https://dash.cloudflare.com/sign-up"
  step "Sign up with your email and a password, then confirm the email Cloudflare sends."
  step "No domain or paid plan is needed: skip any 'add a domain' prompts."
  pause "Press Enter once you can log in to the dashboard."
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log wrangler in to Cloudflare"
if WHOAMI=$(wr whoami --json 2>/dev/null); then
  ok "wrangler is already logged in"
else
  say "wrangler will open a Cloudflare page in your browser."
  step "Log in if asked, then click 'Allow' to let wrangler manage your account."
  note "If no browser opens, copy the link wrangler prints into one."
  pause "Press Enter to start the login."
  wr login || die "wrangler login did not finish." "Re-run and complete the 'Allow' step in the browser."
  WHOAMI=$(wr whoami --json 2>/dev/null) || die "wrangler still isn't logged in after 'wrangler login'."
  ok "wrangler is logged in"
fi
ACCOUNTS=$(printf '%s' "$WHOAMI" | whoami_accounts) || die "Couldn't read the account list from 'wrangler whoami --json'."
[[ -n "$ACCOUNTS" ]] || die "Your Cloudflare login has no accounts." "Finish sign-up in the dashboard, then re-run."
SAVED_ACCOUNT=$(ENV_FILE="$IDS_FILE" _existing CLOUDFLARE_ACCOUNT_ID || true)
if [[ $(printf '%s\n' "$ACCOUNTS" | wc -l) -eq 1 ]]; then
  CF_ACCOUNT_ID=$(printf '%s' "$ACCOUNTS" | cut -f1)
elif [[ -n "$SAVED_ACCOUNT" ]] && printf '%s\n' "$ACCOUNTS" | cut -f1 | grep -qx "$SAVED_ACCOUNT"; then
  CF_ACCOUNT_ID="$SAVED_ACCOUNT"
else
  say "Your login can reach several accounts:"
  i=0
  while IFS=$'\t' read -r id name; do i=$((i + 1)); say "  $i) $name ($id)"; done <<< "$ACCOUNTS"
  read -r -p "  Which one should host the Leaderboard? [1-$i] " pick || die "No account chosen."
  if ! [[ "$pick" =~ ^[0-9]+$ ]] || (( pick < 1 || pick > i )); then die "'$pick' is not one of 1-$i."; fi
  CF_ACCOUNT_ID=$(printf '%s\n' "$ACCOUNTS" | sed -n "${pick}p" | cut -f1)
fi
valid_account_id "$CF_ACCOUNT_ID" || die "wrangler returned an unexpected account id: '$CF_ACCOUNT_ID'."
mkdir -p "$(dirname "$IDS_FILE")"
ENV_FILE="$IDS_FILE" write_env CLOUDFLARE_ACCOUNT_ID "$CF_ACCOUNT_ID"
ok "using account '$(printf '%s\n' "$ACCOUNTS" | grep "^$CF_ACCOUNT_ID" | cut -f2)'"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Pages project '$PAGES_PROJECT'"
say "A Direct Upload project: GitHub Actions deploys it with 'wrangler pages deploy'."
say "Cloudflare's Git integration stays off."
PAGES_LIST=$(wr pages project list --json 2>/dev/null) || die "'wrangler pages project list' failed."
if PAGES_INFO=$(printf '%s' "$PAGES_LIST" | pages_project_info "$PAGES_PROJECT"); then
  ok "project $PAGES_PROJECT already exists"
else
  confirm "Create the Pages project '$PAGES_PROJECT' (production branch '$PAGES_BRANCH')?" \
    || die "Stopped before creating the Pages project."
  wr pages project create "$PAGES_PROJECT" --production-branch "$PAGES_BRANCH" \
    || die "Creating the Pages project failed." "Read wrangler's message above; if the name is in use in your account, delete that project first."
  PAGES_INFO=$(wr pages project list --json 2>/dev/null | pages_project_info "$PAGES_PROJECT") \
    || die "The project was created but doesn't show up in 'wrangler pages project list'."
  ok "created $PAGES_PROJECT"
fi
PAGES_DOMAIN=$(printf '%s' "$PAGES_INFO" | cut -f1)
[[ "$(printf '%s' "$PAGES_INFO" | cut -f2)" == "No" ]] || die "The project '$PAGES_PROJECT' is connected to Git." \
  "We deploy from GitHub Actions instead. Delete it (dashboard → Workers & Pages → $PAGES_PROJECT → Settings → Delete project) and re-run."
ok "site address: https://$PAGES_DOMAIN"
[[ "$PAGES_DOMAIN" == "$PAGES_PROJECT.pages.dev" ]] \
  || warn "Cloudflare gave it $PAGES_DOMAIN, not $PAGES_PROJECT.pages.dev (the name is taken). PLAN.md and README need the real address."
ENV_FILE="$IDS_FILE" write_env PAGES_PROJECT "$PAGES_PROJECT"
ENV_FILE="$IDS_FILE" write_env PAGES_DOMAIN "$PAGES_DOMAIN"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "KV namespaces for the leaderboard data"
say "Two namespaces: '$KV_TITLE' for production and '$KV_PREVIEW_TITLE' for 'wrangler dev'."
for title in "$KV_TITLE" "$KV_PREVIEW_TITLE"; do
  KV_LIST=$(wr kv namespace list 2>/dev/null) || die "'wrangler kv namespace list' failed."
  id=$(printf '%s' "$KV_LIST" | kv_id_for_title "$title") || die "Couldn't read the output of 'wrangler kv namespace list'."
  if [[ -n "$id" ]]; then
    ok "namespace $title already exists"
  else
    preview=()
    [[ "$title" == "$KV_PREVIEW_TITLE" ]] && preview=(--preview)
    wr kv namespace create "$KV_TITLE" "${preview[@]}" >/dev/null || die "Creating the KV namespace $title failed."
    id=$(wr kv namespace list 2>/dev/null | kv_id_for_title "$title" || true)
    [[ -n "$id" ]] || die "Created $title, but it doesn't show up in 'wrangler kv namespace list'."
    ok "created namespace $title"
  fi
  if [[ "$title" == "$KV_TITLE" ]]; then
    ENV_FILE="$IDS_FILE" write_env KV_LEADERBOARD_ID "$id"
  else
    ENV_FILE="$IDS_FILE" write_env KV_LEADERBOARD_PREVIEW_ID "$id"
  fi
done
note "These ids are not secret; the Worker's wrangler config (Sprint 10) takes them from $IDS_FILE."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "CI token for GitHub Actions"
CI_DONE=0
if gh_secret_exists CLOUDFLARE_API_TOKEN && gh_secret_exists CLOUDFLARE_ACCOUNT_ID; then
  ok "GitHub already has CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID"
  confirm "Replace them with a new token?" || CI_DONE=1
fi
if (( CI_DONE == 0 )); then
  say "GitHub Actions deploys the page and the Worker with this token. Create it in the dashboard:"
  open_url "$TOKENS_URL"
  step "Click 'Create Token', then 'Get started' next to 'Create Custom Token'."
  step "Token name: ffp-leaderboard-ci"
  step "Permissions: three rows, each with 'Account' in the first box:"
  say  "      Account · Cloudflare Pages · Edit"
  say  "      Account · Workers Scripts · Edit"
  say  "      Account · Workers KV Storage · Edit"
  step "Account Resources: Include · your account (not 'All accounts')."
  step "Leave Client IP Address Filtering empty (GitHub's runners have no fixed IP) and TTL as you like."
  step "Click 'Continue to summary', check it lists only those three, then 'Create Token'."
  step "Copy the token: Cloudflare shows it only once."
  ask_secret CF_CI_TOKEN "Paste the CI token (hidden):" || die "No token entered."
  [[ -n "$CF_CI_TOKEN" ]] || die "No token entered."
  verify_token "$CF_CI_TOKEN"
  can "$CF_CI_TOKEN" "/pages/projects/$PAGES_PROJECT" || die "The token can't reach the Pages project." \
    "Edit the token: add 'Account · Cloudflare Pages · Edit' on this account, then re-run."
  ok "reaches Cloudflare Pages"
  can "$CF_CI_TOKEN" "/workers/scripts" || die "The token can't reach Workers scripts." \
    "Edit the token: add 'Account · Workers Scripts · Edit' on this account, then re-run."
  ok "reaches Workers Scripts"
  can "$CF_CI_TOKEN" "/storage/kv/namespaces?per_page=5" || die "The token can't reach Workers KV." \
    "Edit the token: add 'Account · Workers KV Storage · Edit' on this account, then re-run."
  ok "reaches Workers KV Storage"
  set_secret CLOUDFLARE_API_TOKEN "$CF_CI_TOKEN"
  unset CF_CI_TOKEN
  set_secret CLOUDFLARE_ACCOUNT_ID "$CF_ACCOUNT_ID"
  if ! gh_secret_exists CLOUDFLARE_API_TOKEN || ! gh_secret_exists CLOUDFLARE_ACCOUNT_ID; then
    die "The GitHub secrets aren't listed on $GH_REPO." "Check you have admin rights on the repository, then re-run."
  fi
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Home push secret (Expected Points to the site)"
say "The Docker job on this machine sends Expected Points to the site, signed with a shared"
say "secret. The site checks the signature and the data before saving it, so a leaked secret"
say "can only send Expected Points, which still have to pass that check."
PUSH_SECRET=$(_existing LEADERBOARD_PUSH_SECRET || true)
NEW_SECRET=0
if [[ -n "$PUSH_SECRET" ]] && valid_push_secret "$PUSH_SECRET"; then
  ok "$SECRETS_FILE already holds a push secret"
else
  PUSH_SECRET=$(make_push_secret)
  NEW_SECRET=1
  write_env LEADERBOARD_PUSH_SECRET "$PUSH_SECRET"
fi
# The deploy job (Sprint 10) hands it to the site with `wrangler pages secret put`.
if (( NEW_SECRET == 0 )) && gh_secret_exists LEADERBOARD_PUSH_SECRET; then
  ok "GitHub secret LEADERBOARD_PUSH_SECRET already set"
else
  set_secret LEADERBOARD_PUSH_SECRET "$PUSH_SECRET"
fi
unset PUSH_SECRET
if [[ -n "$(_existing CLOUDFLARE_KV_PUSH_TOKEN || true)" ]]; then
  for key in CLOUDFLARE_KV_PUSH_TOKEN CLOUDFLARE_ACCOUNT_ID LEADERBOARD_KV_NAMESPACE_ID; do unset_env "$key"; done
  warn "An earlier run made the KV token 'ffp-leaderboard-home-push'. Nothing uses it now, and"
  warn "Cloudflare lets it edit every KV namespace on the account, so delete it:"
  open_url "$TOKENS_URL"
  step "Click '...' next to ffp-leaderboard-home-push, then 'Delete'."
  pause "Press Enter once it's deleted."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "ntfy alerts (optional)"
say "ntfy pushes an alert to your phone when the Worker fails 3 runs in a row, or when"
say "no Expected Points push has arrived for 2 hours on a game day."
say "Anyone who knows the topic name can read and post to it, so it must be unguessable."
NTFY_TOPIC=$(_existing NTFY_TOPIC || true)
if [[ -n "$NTFY_TOPIC" ]] && gh_secret_exists NTFY_TOPIC; then
  ok "ntfy topic already saved in $SECRETS_FILE and on GitHub"
elif confirm "Set up ntfy alerts now? (You can re-run the wizard later.)"; then
  [[ -n "$NTFY_TOPIC" ]] || NTFY_TOPIC=$(make_ntfy_topic)
  valid_ntfy_topic "$NTFY_TOPIC" || die "The saved topic is too short or has odd characters." \
    "Delete the NTFY_TOPIC line from $SECRETS_FILE and re-run for a fresh one."
  step "Install the ntfy app ('ntfy' by Philipp Heckel) from Google Play, F-Droid or the App Store."
  step "In the app tap '+' (Subscribe to topic), keep the server ntfy.sh, and enter this topic:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$NTFY_TOPIC" "$RESET"
  note "This random name is the only protection: don't post it anywhere public."
  pause "Press Enter once you've subscribed, to send a test alert."
  printf 'url = "https://ntfy.sh/%s"\n' "$NTFY_TOPIC" \
    | curl -sS -K - -H "Title: ffp setup" -d "Test alert from setup_cloudflare.sh" >/dev/null \
    || die "Sending the test alert to ntfy.sh failed." "Check your network, then re-run."
  confirm "Did the test alert arrive on your phone?" \
    || die "The test alert didn't arrive." "Check the topic in the app matches exactly (and notifications are allowed), then re-run."
  write_env NTFY_TOPIC "$NTFY_TOPIC"
  set_secret NTFY_TOPIC "$NTFY_TOPIC"
  gh_secret_exists NTFY_TOPIC || die "The NTFY_TOPIC secret isn't listed on $GH_REPO."
else
  SKIPPED+=("ntfy alerts: re-run $SCRIPT_PATH to add them")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Summary"
ok "Cloudflare account  $CF_ACCOUNT_ID"
ok "Pages project       $PAGES_PROJECT → https://$PAGES_DOMAIN (Direct Upload, production branch $PAGES_BRANCH)"
ok "KV namespaces       $KV_TITLE and $KV_PREVIEW_TITLE (ids in $IDS_FILE)"
ok "GitHub secrets      $(gh secret list --json name -q '[.[].name] | join(", ")' 2>/dev/null) on $GH_REPO"
ok "Home push secret    in $SECRETS_FILE (mode 600, gitignored) and on GitHub"
note "Nothing is live yet: the first deploy comes with Sprint 10's GitHub Actions workflow."
printf '\n'
say "${BOLD}To undo a step:${RESET}"
note "  Pages project:  npx $WRANGLER_PKG pages project delete $PAGES_PROJECT"
note "  KV namespaces:  npx $WRANGLER_PKG kv namespace delete --namespace-id <id from $IDS_FILE>"
note "  API tokens:     $TOKENS_URL → '...' next to ffp-leaderboard-ci → Delete"
note "  GitHub secrets: gh secret delete CLOUDFLARE_API_TOKEN (likewise CLOUDFLARE_ACCOUNT_ID, LEADERBOARD_PUSH_SECRET, NTFY_TOPIC)"
note "  ntfy:           unsubscribe in the app; topics need no deleting"
note "  Local files:    rm $IDS_FILE $SECRETS_FILE"
note "  wrangler login: npx $WRANGLER_PKG logout"
pause "Press Enter for the closing checklist."

ENV_FILE="$SECRETS_FILE"
finish
}

run_wizard "$@"; exit
